LANGS = {
    "english": english,
    "hebrew": hebrew,
    "arabic": ARABIC,
    "yiddish": YIDDISH,
    "russian": RUSSIAN,
    "ukrainian": UKRAINIAN,
    "spanish": SPANISH,
    "chinese": CHINESE,
}


def chat_texts(tok, lang):
    """Full chat-template strings, user=QUESTIONS[i], assistant=LANGS[lang][i], enable_thinking=False."""
    return [
        tok.apply_chat_template(
            [{"role": "user", "content": question}, {"role": "assistant", "content": answer}],
            tokenize=False,
            enable_thinking=False,
        )
        for question, answer in zip(QUESTIONS, LANGS[lang])
    ]
